  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --navy: #003B95;
      --blue: #006CE4;
      --gold: #FFB700;
      --gold-dark: #E6A500;
      --white: #fff;
      --gray-50: #F8F9FA;
      --gray-100: #F1F3F5;
      --gray-200: #E9ECEF;
      --gray-400: #ADB5BD;
      --gray-600: #6C757D;
      --gray-700: #495057;
      --gray-900: #212529;
      --radius: 8px;
      --shadow: 0 2px 8px rgba(0,0,0,0.12);
      --shadow-lg: 0 4px 20px rgba(0,0,0,0.15);
    }
    body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; color: var(--gray-900); background: var(--white); line-height: 1.5; }
    a { text-decoration: none; color: inherit; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }

    /* NAV */
    .site-header { background: var(--navy); position: sticky; top: 0; z-index: 100; }
    .header-top { display: flex; align-items: center; justify-content: space-between; padding: 0.75rem 1.5rem; border-bottom: 1px solid rgba(255,255,255,0.15); }
    .logo { color: var(--white); font-size: 1.5rem; font-weight: 800; letter-spacing: -0.5px; }
    .logo span { color: var(--gold); }
    .header-actions { display: flex; gap: 0.75rem; align-items: center; }
    .btn-ghost { color: var(--white); border: 1px solid rgba(255,255,255,0.5); padding: 0.4rem 1rem; border-radius: var(--radius); font-size: 0.875rem; transition: background 0.15s; }
    .btn-ghost:hover { background: rgba(255,255,255,0.1); }
    .btn-primary { background: var(--gold); color: var(--gray-900); padding: 0.4rem 1rem; border-radius: var(--radius); font-size: 0.875rem; font-weight: 600; transition: background 0.15s; }
    .btn-primary:hover { background: var(--gold-dark); }
    .nav-tabs { display: flex; padding: 0 1.5rem; overflow-x: auto; }
    .nav-tabs::-webkit-scrollbar { display: none; }
    .nav-tab { color: rgba(255,255,255,0.8); padding: 0.875rem 1rem; font-size: 0.875rem; white-space: nowrap; border-bottom: 3px solid transparent; transition: color 0.15s, border-color 0.15s; display: flex; align-items: center; gap: 0.4rem; }
    .nav-tab:hover { color: var(--white); }
    .nav-tab.active { color: var(--white); border-bottom-color: var(--white); font-weight: 600; }
    .nav-tab svg { width: 16px; height: 16px; }

    /* HERO */
    .hero { background: linear-gradient(135deg, var(--navy) 0%, #005ab5 100%); padding: 3rem 1.5rem 4rem; }
    .hero h1 { color: var(--white); font-size: clamp(1.75rem, 4vw, 2.5rem); font-weight: 800; margin-bottom: 0.5rem; }
    .hero p { color: rgba(255,255,255,0.85); font-size: 1.1rem; margin-bottom: 2rem; }
    .search-box { background: var(--white); border-radius: var(--radius); padding: 1rem; display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: flex-end; box-shadow: var(--shadow-lg); max-width: 900px; }
    .search-field { flex: 1; min-width: 160px; }
    .search-field label { display: block; font-size: 0.75rem; font-weight: 600; color: var(--gray-700); margin-bottom: 0.25rem; text-transform: uppercase; letter-spacing: 0.5px; }
    .search-field input, .search-field select { width: 100%; border: 1px solid var(--gray-200); border-radius: 6px; padding: 0.6rem 0.75rem; font-size: 0.9rem; color: var(--gray-900); outline: none; transition: border-color 0.15s; font-family: inherit; }
    .search-field input:focus, .search-field select:focus { border-color: var(--blue); }
    .search-btn { background: var(--blue); color: var(--white); padding: 0.65rem 2rem; border-radius: 6px; font-size: 1rem; font-weight: 700; transition: background 0.15s; white-space: nowrap; }
    .search-btn:hover { background: #005ab5; }
    .search-extras { margin-top: 0.75rem; display: flex; align-items: center; gap: 0.5rem; font-size: 0.85rem; color: rgba(255,255,255,0.85); }
    .search-extras input[type="checkbox"] { accent-color: var(--gold); width: 16px; height: 16px; }

    /* SECTIONS */
    .section { padding: 3rem 1.5rem; }
    .section-alt { background: var(--gray-50); }
    .section-header { margin-bottom: 1.75rem; }
    .section-header h2 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 800; color: var(--gray-900); margin-bottom: 0.25rem; }
    .section-header p { color: var(--gray-600); font-size: 0.95rem; }
    .container { max-width: 1200px; margin: 0 auto; }

    /* TRUST BADGES */
    .trust-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 1.5rem; }
    .trust-card { display: flex; gap: 1rem; align-items: flex-start; }
    .trust-icon { width: 48px; height: 48px; background: var(--blue); border-radius: 12px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .trust-icon svg { width: 24px; height: 24px; color: var(--white); }
    .trust-card h3 { font-size: 0.95rem; font-weight: 700; margin-bottom: 0.2rem; }
    .trust-card p { font-size: 0.8rem; color: var(--gray-600); line-height: 1.4; }

    /* OFFERS */
    .offers-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1.5rem; }
    .offer-card { border-radius: var(--radius); overflow: hidden; position: relative; min-height: 200px; display: flex; align-items: flex-end; }
    .offer-card.navy { background: linear-gradient(135deg, var(--navy), #005ab5); }
    .offer-card.gold { background: linear-gradient(135deg, #8B4513, #C0642C); }
    .offer-content { padding: 1.5rem; color: var(--white); }
    .offer-content h3 { font-size: 1.1rem; font-weight: 800; margin-bottom: 0.5rem; line-height: 1.3; }
    .offer-content p { font-size: 0.85rem; opacity: 0.9; margin-bottom: 1rem; line-height: 1.4; }
    .btn-offer { display: inline-block; background: var(--gold); color: var(--gray-900); padding: 0.5rem 1.25rem; border-radius: 6px; font-weight: 700; font-size: 0.875rem; transition: background 0.15s; }
    .btn-offer:hover { background: var(--gold-dark); }
    .btn-offer-outline { display: inline-block; border: 2px solid var(--white); color: var(--white); padding: 0.5rem 1.25rem; border-radius: 6px; font-weight: 700; font-size: 0.875rem; transition: background 0.15s; }
    .btn-offer-outline:hover { background: rgba(255,255,255,0.15); }

    /* PROPERTY TYPES */
    .type-cloud { display: flex; flex-wrap: wrap; gap: 0.5rem; }
    .type-chip { border: 1px solid var(--gray-200); border-radius: 20px; padding: 0.4rem 1rem; font-size: 0.875rem; color: var(--gray-700); transition: border-color 0.15s, color 0.15s; cursor: pointer; }
    .type-chip:hover { border-color: var(--blue); color: var(--blue); }

    /* TABS */
    .tabs { display: flex; gap: 0; border-bottom: 2px solid var(--gray-200); overflow-x: auto; margin-bottom: 1.5rem; }
    .tabs::-webkit-scrollbar { display: none; }
    .tab-btn { padding: 0.6rem 1rem; font-size: 0.875rem; font-weight: 500; color: var(--gray-600); border-bottom: 2px solid transparent; margin-bottom: -2px; white-space: nowrap; transition: color 0.15s, border-color 0.15s; }
    .tab-btn.active { color: var(--navy); border-bottom-color: var(--navy); font-weight: 700; }
    .tab-btn:hover:not(.active) { color: var(--gray-900); }
    .tab-panel { display: none; }
    .tab-panel.active { display: block; }

    /* DESTINATION CARDS */
    .dest-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 0.75rem; }
    .dest-card { border-radius: var(--radius); overflow: hidden; border: 1px solid var(--gray-200); transition: box-shadow 0.15s; cursor: pointer; }
    .dest-card:hover { box-shadow: var(--shadow); }
    .dest-img { width: 100%; height: 90px; background: linear-gradient(135deg, #4a90d9, #357abd); position: relative; overflow: hidden; }
    .dest-img-placeholder { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; font-size: 1.5rem; }
    .dest-name { font-size: 0.8rem; font-weight: 700; padding: 0.4rem 0.5rem 0.1rem; }
    .dest-dist { font-size: 0.72rem; color: var(--gray-600); padding: 0 0.5rem 0.4rem; }

    /* CAROUSEL */
    .carousel-wrap { position: relative; }
    .carousel { display: flex; gap: 1rem; overflow-x: auto; scroll-snap-type: x mandatory; padding-bottom: 0.5rem; scroll-behavior: smooth; }
    .carousel::-webkit-scrollbar { height: 4px; }
    .carousel::-webkit-scrollbar-track { background: var(--gray-200); border-radius: 2px; }
    .carousel::-webkit-scrollbar-thumb { background: var(--gray-400); border-radius: 2px; }
    .carousel-btn { position: absolute; top: 50%; transform: translateY(-50%); background: var(--white); border: 1px solid var(--gray-200); border-radius: 50%; width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; box-shadow: var(--shadow); z-index: 10; transition: box-shadow 0.15s; }
    .carousel-btn:hover { box-shadow: var(--shadow-lg); }
    .carousel-btn.prev { left: -16px; }
    .carousel-btn.next { right: -16px; }
    .carousel-btn svg { width: 18px; height: 18px; color: var(--gray-700); }

    /* PROPERTY CARDS */
    .prop-card { flex: 0 0 260px; scroll-snap-align: start; border-radius: var(--radius); border: 1px solid var(--gray-200); overflow: hidden; transition: box-shadow 0.15s; }
    .prop-card:hover { box-shadow: var(--shadow-lg); }
    .prop-img { width: 100%; height: 160px; background: linear-gradient(135deg, #5b8dd9, #3a6bb5); display: flex; align-items: center; justify-content: center; font-size: 2rem; }
    .prop-body { padding: 0.875rem; }
    .prop-name { font-size: 0.9rem; font-weight: 700; margin-bottom: 0.2rem; line-height: 1.3; }
    .prop-loc { font-size: 0.78rem; color: var(--gray-600); margin-bottom: 0.5rem; }
    .prop-meta { display: flex; align-items: center; justify-content: space-between; }
    .badge { display: inline-flex; align-items: center; gap: 0.25rem; background: var(--navy); color: var(--white); font-size: 0.75rem; font-weight: 700; padding: 0.2rem 0.4rem; border-radius: 4px; }
    .badge-label { font-size: 0.75rem; color: var(--gray-600); }
    .prop-price { text-align: right; }
    .prop-price .original { text-decoration: line-through; color: var(--gray-600); font-size: 0.75rem; }
    .prop-price .current { font-size: 1rem; font-weight: 800; color: var(--gray-900); }
    .prop-price .per-night { font-size: 0.7rem; color: var(--gray-600); }

    /* GRID CARDS */
    .card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 1rem; }
    .card-grid-2 { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1rem; }
    .explore-card { border-radius: var(--radius); overflow: hidden; border: 1px solid var(--gray-200); transition: box-shadow 0.15s; cursor: pointer; }
    .explore-card:hover { box-shadow: var(--shadow); }
    .explore-img { width: 100%; height: 120px; display: flex; align-items: center; justify-content: center; font-size: 2rem; }
    .explore-body { padding: 0.75rem; }
    .explore-city { font-weight: 700; font-size: 0.9rem; }
    .explore-count { font-size: 0.78rem; color: var(--gray-600); margin-top: 0.1rem; }

    /* TRENDING */
    .trending-row { display: flex; flex-wrap: wrap; gap: 0.75rem; }
    .trending-tag { display: flex; align-items: center; gap: 0.5rem; background: var(--gray-100); border-radius: 20px; padding: 0.4rem 0.875rem; font-size: 0.875rem; font-weight: 500; cursor: pointer; transition: background 0.15s; }
    .trending-tag:hover { background: var(--gray-200); }
    .trend-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--gold); }

    /* DEAL CARDS */
    .deal-card { border: 1px solid var(--gray-200); border-radius: var(--radius); overflow: hidden; display: flex; flex-direction: column; transition: box-shadow 0.15s; }
    .deal-card:hover { box-shadow: var(--shadow); }
    .deal-img { height: 160px; display: flex; align-items: center; justify-content: center; font-size: 2.5rem; }
    .deal-body { padding: 0.875rem; flex: 1; display: flex; flex-direction: column; gap: 0.5rem; }
    .deal-name { font-weight: 700; font-size: 0.9rem; line-height: 1.3; }
    .deal-loc { font-size: 0.78rem; color: var(--gray-600); }
    .deal-rating-row { display: flex; align-items: center; gap: 0.5rem; }
    .deal-footer { display: flex; align-items: flex-end; justify-content: space-between; margin-top: auto; }
    .deal-nights { font-size: 0.78rem; color: var(--gray-600); }
    .deal-price .was { text-decoration: line-through; color: var(--gray-400); font-size: 0.8rem; }
    .deal-price .now { font-size: 1.1rem; font-weight: 800; color: var(--navy); }

    /* HOMES */
    .home-card { border: 1px solid var(--gray-200); border-radius: var(--radius); overflow: hidden; transition: box-shadow 0.15s; }
    .home-card:hover { box-shadow: var(--shadow); }
    .home-img { height: 180px; display: flex; align-items: center; justify-content: center; font-size: 2rem; }
    .home-body { padding: 0.875rem; }
    .home-name { font-weight: 700; font-size: 0.9rem; margin-bottom: 0.2rem; }
    .home-loc { font-size: 0.78rem; color: var(--gray-600); margin-bottom: 0.5rem; }
    .home-footer { display: flex; align-items: center; justify-content: space-between; }
    .home-price { font-weight: 800; font-size: 1rem; }

    /* LOYALTY */
    .loyalty-section { background: var(--navy); color: var(--white); }
    .loyalty-inner { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1.5rem; }
    .loyalty-text h2 { font-size: 1.5rem; font-weight: 800; margin-bottom: 0.25rem; }
    .loyalty-text p { font-size: 0.875rem; opacity: 0.85; max-width: 450px; line-height: 1.5; }
    .loyalty-text .sub { font-size: 1rem; font-weight: 600; opacity: 0.9; margin-bottom: 0.4rem; }
    .loyalty-btns { display: flex; gap: 0.75rem; flex-wrap: wrap; margin-top: 1rem; }
    .btn-white { background: var(--white); color: var(--navy); padding: 0.6rem 1.5rem; border-radius: 6px; font-weight: 700; font-size: 0.9rem; transition: opacity 0.15s; }
    .btn-white:hover { opacity: 0.9; }
    .btn-white-outline { border: 2px solid var(--white); color: var(--white); padding: 0.6rem 1.5rem; border-radius: 6px; font-weight: 700; font-size: 0.9rem; transition: background 0.15s; }
    .btn-white-outline:hover { background: rgba(255,255,255,0.1); }

    /* POPULAR LINKS */
    .link-grid { display: flex; flex-wrap: wrap; gap: 0.5rem; }
    .pop-link { color: var(--blue); font-size: 0.875rem; transition: color 0.15s; }
    .pop-link:hover { color: var(--navy); text-decoration: underline; }

    /* FOOTER */
    footer { background: var(--gray-900); color: var(--white); padding: 3rem 1.5rem 1.5rem; }
    .footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 2rem; margin-bottom: 2rem; }
    .footer-col h4 { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--gray-400); margin-bottom: 0.875rem; }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 0.5rem; }
    .footer-col a { font-size: 0.85rem; color: rgba(255,255,255,0.7); transition: color 0.15s; }
    .footer-col a:hover { color: var(--white); }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 1.5rem; font-size: 0.8rem; color: rgba(255,255,255,0.5); text-align: center; line-height: 1.6; }

    /* COLORS FOR IMG PLACEHOLDERS */
    .bg-1 { background: linear-gradient(135deg, #667eea, #764ba2); }
    .bg-2 { background: linear-gradient(135deg, #f093fb, #f5576c); }
    .bg-3 { background: linear-gradient(135deg, #4facfe, #00f2fe); }
    .bg-4 { background: linear-gradient(135deg, #43e97b, #38f9d7); }
    .bg-5 { background: linear-gradient(135deg, #fa709a, #fee140); }
    .bg-6 { background: linear-gradient(135deg, #a18cd1, #fbc2eb); }
    .bg-7 { background: linear-gradient(135deg, #ffecd2, #fcb69f); }
    .bg-8 { background: linear-gradient(135deg, #a1c4fd, #c2e9fb); }
    .bg-9 { background: linear-gradient(135deg, #d4fc79, #96e6a1); }
    .bg-10 { background: linear-gradient(135deg, #f6d365, #fda085); }

    @media (max-width: 600px) {
      .header-top { padding: 0.75rem 1rem; }
      .hero { padding: 2rem 1rem 3rem; }
      .search-box { padding: 0.75rem; }
      .section { padding: 2rem 1rem; }
    }
  </style>
</head>
<body>

<!-- HEADER -->
<header class="site-header">
  <div class="header-top">
    <a href="index.html" class="logo">Stay<span>Quest</span></a>
    <div class="header-actions">
      <a href="#" class="btn-ghost">List your property</a>
      <a href="#" class="btn-ghost">?</a>
      <a href="#" class="btn-ghost">Sign in</a>
      <a href="#" class="btn-primary">Register</a>
    </div>
  </div>
  <nav class="nav-tabs">
    <a href="index.html" class="nav-tab active">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>
      Stays
