    <a href="#" class="nav-tab">Cruises</a>
    <a href="attractions.html" class="nav-tab">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
      Attractions
    </a>
    <a href="#" class="nav-tab">Airport taxis</a>
  </nav>
</header>

<!-- HERO -->
<section class="hero">
  <div class="container">
    <h1>Find deals for any season</h1>
    <p>From cozy bed &amp; breakfasts to luxury hotels</p>
    <div class="search-box">
      <div class="search-field" style="flex:2;min-width:200px;">
        <label>Destination</label>
        <input type="text" placeholder="Where are you going?">
      </div>
      <div class="search-field">
        <label>Check-in</label>
        <input type="date">
      </div>
      <div class="search-field">
        <label>Check-out</label>
        <input type="date">
      </div>
      <div class="search-field">
        <label>Guests &amp; rooms</label>
        <input type="text" value="2 adults · 0 children · 1 room">
      </div>
      <button class="search-btn">Search</button>
    </div>
    <div class="search-extras">
      <input type="checkbox" id="add-flights">
      <label for="add-flights">Add flights to my search</label>
    </div>
  </div>
</section>

<!-- TRUST BADGES -->
<section class="section">
  <div class="container">
    <div class="trust-grid">
      <div class="trust-card">
        <div class="trust-icon">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
        </div>
        <div>
