  // Generic tab switcher
  function initTabs(containerSelector, panelPrefix) {
    const container = document.querySelector(containerSelector);
    if (!container) return;
    container.addEventListener('click', e => {
      const btn = e.target.closest('.tab-btn');
      if (!btn) return;
      container.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const tabId = btn.dataset.tab;
      document.querySelectorAll(`[id^="tab-${panelPrefix}"]`).forEach(p => p.classList.remove('active'));
      const panel = document.getElementById(`tab-${tabId}`);
      if (panel) panel.classList.add('active');
    });
  }

  initTabs('#trip-tabs', 'festivals');
  // For trip tabs, we need a custom approach since panel ids don't share a single prefix
  document.getElementById('trip-tabs').addEventListener('click', e => {
    const btn = e.target.closest('.tab-btn');
    if (!btn) return;
