    btn.classList.add('active');
    document.querySelectorAll('#tab-festivals, #tab-theme-parks, #tab-beaches, #tab-cultural, #tab-food, #tab-city, #tab-wine, #tab-outdoor, #tab-nature, #tab-history').forEach(p => p.classList.remove('active'));
