<script>
  function makeTabGroup(tabsId, panelIds) {
    const container = document.getElementById(tabsId);
    if (!container) return;
    container.addEventListener('click', e => {
      const btn = e.target.closest('.tab-btn');
      if (!btn) return;
      container.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      panelIds.forEach(id => {
        const p = document.getElementById(id);
        if (p) p.classList.remove('active');
      });
      const panel = document.getElementById(`tab-${btn.dataset.tab}`);
      if (panel) panel.classList.add('active');
    });
  }

  makeTabGroup('region-tabs', [
    'tab-region-europe','tab-region-namerica','tab-region-asia','tab-region-africa',
    'tab-region-oceania','tab-region-mideast','tab-region-caribbean','tab-region-samerica','tab-region-camerica'
  ]);

  makeTabGroup('things-tabs', [
    'tab-things-tours','tab-things-city','tab-things-museums','tab-things-entertainment',
    'tab-things-activities','tab-things-transport','tab-things-food','tab-things-outdoor',
    'tab-things-parks','tab-things-nightlife'
  ]);
</script>
